initialization.exact_callback:
% Embedded verbatim in the model InitFcn; no helper file is needed to run SLX.
teach_model = bdroot;
teach_workspace = get_param(teach_model,'ModelWorkspace');
teach_cfg_path = [teach_model '/时序设置'];
teach_divider = str2double(get_param(teach_cfg_path,'speed_divider'));
teach_cycles = str2double(get_param(teach_cfg_path,'pwm_cycles'));
validateattributes(teach_divider,{'double'},{'scalar','real','finite','integer','>=',1,'<=',1000});
validateattributes(teach_cycles,{'double'},{'scalar','real','finite','integer','>=',1,'<=',20});
teach_dt = getVariable(teach_workspace,'dt');
teach_period = getVariable(teach_workspace,'Ts_speed');
if strcmp(get_param(teach_cfg_path,'speed_on'),'on')
    teach_period = teach_dt*teach_divider;
end
assert(teach_period >= teach_dt && abs(teach_period/teach_dt-round(teach_period/teach_dt))<1e-9, ...
    '速度环周期必须为电流控制周期的正整数倍。');
teach_names = {'teaching_Ts_speed','teach_pwm_on','teach_pwm_cycles'};
teach_values_to_set = {teach_period,double(strcmp(get_param(teach_cfg_path,'pwm_on'),'on')),teach_cycles};
for teach_index = 1:numel(teach_names)
    if ~isequaln(getVariable(teach_workspace,teach_names{teach_index}),teach_values_to_set{teach_index})
        assignin(teach_workspace,teach_names{teach_index},teach_values_to_set{teach_index});
    end
end


assignin(get_param(bdroot,'ModelWorkspace'),'decoupling_enabled',double(strcmp(get_param([bdroot '/解耦'],'enabled'),'on')));
% Embedded in InitFcn after the pre-existing teaching initialization.
tim_m=bdroot;tim_ws=get_param(tim_m,'ModelWorkspace');tim_path=[tim_m '/时序设置'];
tim_on=double(strcmp(get_param(tim_path,'real_on'),'on'));
tim_period=getVariable(tim_ws,'dt');tim_speed=getVariable(tim_ws,'teaching_Ts_speed');
tim_trigger=str2double(get_param(tim_path,'trigger_us'))*1e-6;
tim_sync=str2double(get_param(tim_path,'sync_us'))*1e-6;
tim_compute=str2double(get_param(tim_path,'compute_us'))*1e-6;
tim_guard=str2double(get_param(tim_path,'settle_us'))*1e-6;
tim_window=double(strcmp(get_param(tim_path,'window_on'),'on'));
tim_hold=double(strcmp(get_param(tim_path,'invalid_hold_on'),'on'));
tim_mode=double(strcmp(get_param(tim_path,'update_mode'),'仅谷底（对照）'));
tim_h=1e-6;tim_control=tim_period;tim_speed_sample=tim_speed;
tim_static=-1;
tim_carrier=[0 tim_period/2 0];
validateattributes([tim_trigger tim_sync tim_compute tim_guard],{'double'},{'real','finite','nonnegative'});
if tim_on
 assert(strcmp(get_param(tim_path,'pwm_on'),'off'),'真实时序与旧整周期输出延迟不可同时启用。');
 assert(strcmp(get_param([tim_m '/采样设置'],'delay_on'),'off'),'真实时序与旧整周期采样延迟不可同时启用。');
 tim_h=62.5e-9;
 tim_grid_divider=str2double(get_param(tim_path,'grid_divider'));
 validateattributes(tim_grid_divider,{'double'},{'scalar','integer','>=',1,'<=',2});
 % Optional finer grid for convergence checks, still configured explicitly.
 tim_h=tim_h/tim_grid_divider;
 validateattributes(tim_h,{'double'},{'scalar','finite','positive'});
 tim_jeos=tim_trigger+tim_sync+4.5e-6;
 assert(tim_compute>=tim_h,'计算耗时至少为一个事件网格，避免写入读取同拍未完成指令。');
 assert(tim_jeos+tim_compute<tim_period,'本版要求整组转换及计算在同一PWM周期内完成。');
 assert(tim_jeos>0 && tim_jeos<tim_period);
 timing_grid_values=[tim_trigger tim_sync tim_compute tim_guard 1.1875e-6 1.5e-6 tim_period tim_speed];
 assert(all(abs(timing_grid_values/tim_h-round(timing_grid_values/tim_h))<1e-7),'事件时间必须落在62.5ns（或更细）网格上。');
 tim_control=[tim_period tim_jeos];
 tim_static=0;
 tim_speed_sample=[tim_speed tim_jeos+tim_speed-tim_period];
 % Existing comparator is carrier>=threshold; inverted carrier implements PWM1.
 tim_carrier=[tim_period/2 0 tim_period/2];
else
 assert(~tim_window && ~tim_hold,'有效窗口及无效值保持需要先开启真实时序。');
end
assert(~tim_hold || tim_window,'无效值保持需要同时开启低侧采样窗口。');
tim_adc_cfg=[tim_on tim_window tim_hold tim_h tim_period tim_trigger 1.1875e-6 1.5e-6 tim_sync tim_guard tim_speed/tim_period];
tim_pwm_cfg=[tim_on tim_h tim_period tim_trigger 1.1875e-6 1.5e-6 tim_sync tim_compute tim_mode 4000];
tim_names={'timing_on','timing_h','timing_control_sample','timing_speed_sample','timing_carrier_y','timing_adc_cfg','timing_pwm_cfg','timing_static_math'};
tim_vals={tim_on,tim_h,tim_control,tim_speed_sample,tim_carrier,tim_adc_cfg,tim_pwm_cfg,tim_static};
for tim_k=1:numel(tim_names),assignin(tim_ws,tim_names{tim_k},tim_vals{tim_k});end
set_param(tim_m,'FixedStep','timing_h');

% Append after existing timing InitFcn. Defaults preserve the timing baseline.
dead_m=bdroot;dead_ws=get_param(dead_m,'ModelWorkspace');dead_path=[dead_m '/功率设置'];
dead_gate=double(strcmp(get_param(dead_path,'gate_on'),'on'));
dead_comp=double(strcmp(get_param(dead_path,'comp_on'),'on'));
dead_dt=str2double(get_param(dead_path,'gate_us'))*1e-6;
dead_ct=str2double(get_param(dead_path,'comp_us'))*1e-6;
dead_band=str2double(get_param(dead_path,'hysteresis_A'));
dead_zero=str2double(get_param(dead_path,'zero_A'));
validateattributes([dead_dt dead_ct dead_band dead_zero],{'double'},{'real','finite','nonnegative'});
assert(~dead_comp||dead_gate,'先启用门极死区，再启用补偿，避免给理想桥额外施加电压误差。');
assert(~dead_gate||strcmp(get_param(dead_path,'dead_on'),'off'),'真实门极死区与旧平均死区压降互斥，避免重复计算。');
dead_step=getVariable(dead_ws,'timing_h');
if dead_gate
 assert(abs(getVariable(dead_ws,'Ld')-getVariable(dead_ws,'Lq'))<1e-12,'本轮近零续流模型适用于当前Ld=Lq的PMSM。');
 dead_step=min(dead_step,62.5e-9);
 assert(dead_dt<getVariable(dead_ws,'Ts')/4,'死区应小于PWM周期的四分之一。');
 assert(abs(dead_dt/dead_step-round(dead_dt/dead_step))<1e-7,'门极死区必须落在事件网格上。');
 assignin(dead_ws,'timing_h',dead_step);
end
dead_drop=double(strcmp(get_param(dead_path,'drop_on'),'on'));
assignin(dead_ws,'dead_gate_on',dead_gate);assignin(dead_ws,'dead_h',dead_step);
assignin(dead_ws,'dead_gate_cfg',[dead_gate dead_step dead_dt]);
assignin(dead_ws,'dead_comp_cfg',[dead_comp dead_ct getVariable(dead_ws,'Ts') dead_band]);
assignin(dead_ws,'dead_bridge_cfg',[getVariable(dead_ws,'p') getVariable(dead_ws,'phis') dead_zero dead_drop ...
 str2double(get_param(dead_path,'ron')) str2double(get_param(dead_path,'vf'))]);
set_param(dead_m,'FixedStep','timing_h');
